    private val cache = mutableMapOf<String, ImageVector>()

    fun get(name: String): ImageVector {
        return cache.getOrPut(name) {
            val pathString = rawPaths[name] ?: rawPaths["widgets"]!!
            val nodes = PathParser().parsePathString(pathString).toNodes()
            ImageVector.Builder(
                name = name,
                defaultWidth = 24.dp,
                defaultHeight = 24.dp,
                viewportWidth = 24f,
                viewportHeight = 24f
            ).addPath(
                pathData = nodes,
                pathFillType = PathFillType.NonZero,
                fill = SolidColor(Color.White)
            ).build()
        }
    }
}
